/** The view entity's registry entries (see src/graph/). */
import { NO_CANVAS, NO_CATALOG, NO_DATA, NO_LIFECYCLE, } from "../../graph/types.js";
import { AGENT_VIEW_RESOURCE_TYPE, CALENDAR_VIEW_RESOURCE_TYPE, DASHBOARD_VIEW_RESOURCE_TYPE, KANBAN_VIEW_RESOURCE_TYPE, LAYOUT_RESOURCE_TYPE, LIST_VIEW_RESOURCE_TYPE, MANAGED_VIEW_ORDER_RESOURCE_TYPE, } from "./types.js";
/**
 * Layouts + list views are stream members folded into the app authoring file
 * (inline), extracted by `appFromTf` — not own-file kinds.
 */
export const viewModule = {
    kind: "view",
    stream: { role: "streamMember" },
    authoring: { unit: "inline", bag: "views" },
    parents: [
        { parent: "app", child: "view" },
        { parent: "element", child: "view" },
    ],
    resource: {
        shape: "subTypes",
        rows: [
            { key: "layout", resourceType: LAYOUT_RESOURCE_TYPE, implemented: true },
            { key: "listView", resourceType: LIST_VIEW_RESOURCE_TYPE, implemented: true },
            { key: "agentView", resourceType: AGENT_VIEW_RESOURCE_TYPE, implemented: true },
            { key: "calendarView", resourceType: CALENDAR_VIEW_RESOURCE_TYPE, implemented: true },
            { key: "dashboardView", resourceType: DASHBOARD_VIEW_RESOURCE_TYPE, implemented: true },
            { key: "kanbanView", resourceType: KANBAN_VIEW_RESOURCE_TYPE, implemented: true },
        ],
    },
    data: NO_DATA,
    lifecycle: NO_LIFECYCLE,
    canvas: NO_CANVAS,
    catalog: NO_CATALOG,
};
/**
 * `elementum_managed_view_order` is a singleton per aspect with no identity
 * of its own: its import/state id is the owning app or element id. That id is
 * therefore intentionally shared with the owner's resource at a different
 * Terraform resource type, just like `elementum_record_create_form`.
 * Adoption scopes identity by resource type, so both bindings can be safely
 * imported and recognized on re-pull. Leaving this resource unadopted makes a
 * freshly pulled workspace plan a create that would reorder the live views.
 */
export const managedViewOrderModule = {
    kind: "managed-view-order",
    stream: { role: "streamMember" },
    authoring: { unit: "inline", bag: "views" },
    parents: [
        { parent: "app", child: "managed-view-order" },
        { parent: "element", child: "managed-view-order" },
    ],
    resource: {
        shape: "single",
        resourceType: MANAGED_VIEW_ORDER_RESOURCE_TYPE,
        adoptable: true,
    },
    data: NO_DATA,
    lifecycle: NO_LIFECYCLE,
    canvas: NO_CANVAS,
    catalog: NO_CATALOG,
};
